// Reuse the cached OpenSky JWT if it's still valid; only hit the auth
// endpoint when it's missing or about to expire (60s safety margin).
const cfg = $('Config (edit per location)').item.json;
const staticData = $getWorkflowStaticData('global');
const now = Math.floor(Date.now() / 1000);
const SAFETY_MARGIN = 60;

if (staticData.openskyToken && staticData.openskyTokenExpiry && now < staticData.openskyTokenExpiry - SAFETY_MARGIN) {
  return [{ json: { access_token: staticData.openskyToken } }];
}

const bodyParams = Object.entries({
  grant_type: 'client_credentials',
  client_id: cfg.OPENSKY_CLIENT_ID,
  client_secret: cfg.OPENSKY_CLIENT_SECRET
}).map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&');

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://auth.opensky-network.org/auth/realms/opensky-network/protocol/openid-connect/token',
  body: bodyParams,
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
});

staticData.openskyToken = response.access_token;
staticData.openskyTokenExpiry = now + (response.expires_in || 1800);

return [{ json: { access_token: response.access_token } }];

// Find the aircraft closest to HOME_LAT/HOME_LON among the returned states.
// OpenSky state vector indices: 0=icao24, 1=callsign, 5=lon, 6=lat, 7=baro_altitude(m), 8=on_ground
const cfg = $('Config (edit per location)').item.json;
const states = $input.first().json.states || [];

function haversineKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

const candidates = states
  .filter(s => s[5] !== null && s[6] !== null && s[1] && s[1].trim() && s[8] === false)
  .map(s => ({
    icao24: s[0],
    callsign: s[1].trim(),
    lon: s[5],
    lat: s[6],
    altitude: s[7],
    distanceKm: haversineKm(cfg.HOME_LAT, cfg.HOME_LON, s[6], s[5])
  }))
  .sort((a, b) => a.distanceKm - b.distanceKm);

if (candidates.length === 0) {
  return [{ json: { found: false } }];
}

return [{ json: { found: true, ...candidates[0] } }];

const nearest = $('Nearest Aircraft').item.json;
const routeResp = $('Lookup Route (adsbdb)').item.json;
const aircraftResp = $input.first().json;

const route = routeResp && routeResp.response && routeResp.response.flightroute;
// adsbdb returns { response: "unknown aircraft" } (a string) on no match --
// aircraftResp.response.aircraft is safely undefined in that case, not a crash.
const aircraft = aircraftResp && aircraftResp.response && aircraftResp.response.aircraft;

const altitudeFt = (nearest.altitude !== null && nearest.altitude !== undefined)
  ? Math.round(nearest.altitude * 3.28084)
  : null;

const payload = {
  flight: nearest.callsign,
  altitudeFt
};

// Codes with a preloaded icon in icons/ (tools/convert_tiles.py output).
// Regenerate this list whenever icons/ changes:
//   ls icons | sed "s/_logo\.bin$//" | sort
// "00" is the blank tail icon, shown whenever neither the airline's IATA
// nor ICAO code has one -- keeps a missing logo from looking like a bug
// instead of just "no airline art for this one yet".
const AVAILABLE_ICONS = new Set(["00", "1i", "2k", "2l", "2p", "2q", "3k", "3l", "3m", "3o", "3u", "3v", "3y", "4c", "4y", "5h", "5j", "5o", "5t", "5w", "5x", "5y", "6b", "6e", "7c", "7g", "8c", "9c", "9e", "9p", "9t", "9w", "a0", "a3", "a5", "aa", "ab", "ac", "ad", "adb", "af", "ai", "ak", "am", "an", "ao", "ar", "as", "asy", "at", "av", "ax", "ay", "az", "b6", "ba", "bc", "bd", "be", "bf", "bi", "br", "bs", "bt", "bw", "by", "bz", "c5", "c8", "ca", "cc", "cfc", "ci", "ck", "cl", "cm", "cp", "cul", "cv", "cx", "cz", "d0", "d5", "d7", "d8", "dd", "de", "dh", "dj", "dl", "ds", "dx", "dy", "e4", "e5", "e6", "ea", "eb", "ec", "eh", "ei", "ek", "en", "es", "et", "ew", "ey", "f8", "f9", "fc", "fd", "fi", "fj", "fr", "fx", "fz", "g3", "g4", "g7", "g9", "ga", "gaf", "gb", "gf", "gk", "gl", "gu", "ha", "hb", "hd", "hk", "ho", "hu", "hv", "hx", "hy", "i2", "ib", "id", "ir", "it", "iw", "j2", "j4", "j9", "jc", "jj", "jl", "jm", "jo", "jq", "jt", "ju", "jx", "k4", "kc", "kda", "ke", "ki", "kl", "kn", "kq", "kt", "ku", "l3", "la", "lg", "lh", "lj", "ll", "lm", "lo", "lp", "lr", "ls", "lu", "lx", "ly", "me", "mf", "mh", "mi", "mk", "mm", "mp", "mq", "ms", "mu", "mx", "mzn", "n0", "n3", "n6", "n8", "nc", "nh", "nk", "nu", "nw", "nz", "o6", "od", "oh", "ok", "oo", "or", "os", "ou", "ow", "oy", "oz", "p9", "pa", "pb", "pc", "pd", "pg", "ph", "pk", "po", "pr", "ps", "pt", "pu", "px", "pz", "q6", "qf", "qk", "qp", "qq", "qr", "qt", "qx", "qy", "qz", "rch", "rfds", "rh", "rj", "rk", "ro", "rr", "rrr", "s4", "s7", "s8", "sa", "sb", "sg", "sh", "sk", "sl", "sn", "sq", "ss", "su", "sv", "sy", "ta", "tb", "tfx", "tg", "tk", "tl", "tn", "to", "tp", "tr", "ts", "tw", "u2", "ua", "uc", "uk", "ul", "uo", "ups", "us", "ut", "ux", "v7", "va", "vj", "vl", "vn", "vo", "vs", "vw", "vy", "vz", "w4", "w6", "w8", "w9", "wa", "wg", "wgn", "wk", "wn", "wr", "ws", "wy", "x3", "xe", "xj", "xk", "xl", "xm", "xp", "xq", "y4", "yp", "yw", "yx", "z0", "z2", "zh", "zl"]);

function resolveIcon(iata, icao) {
  if (iata && AVAILABLE_ICONS.has(iata)) return `${iata}_logo`;
  if (icao && AVAILABLE_ICONS.has(icao)) return `${icao}_logo`;
  return '00_logo';
}

if (route) {
  const airlineIata = route.airline && route.airline.iata ? route.airline.iata.toLowerCase() : null;
  const airlineIcao = route.airline && route.airline.icao ? route.airline.icao.toLowerCase() : null;
  if (route.airline && route.airline.name) payload.airline = route.airline.name;
  payload.originCode = route.origin ? (route.origin.iata_code || route.origin.icao_code) : null;
  payload.destCode = route.destination ? (route.destination.iata_code || route.destination.icao_code) : null;
  payload.originCity = route.origin ? (route.origin.name || route.origin.municipality) : null;
  payload.destCity = route.destination ? (route.destination.name || route.destination.municipality) : null;
  payload.icon = resolveIcon(airlineIata, airlineIcao);
} else {
  payload.icon = '00_logo';
}

if (aircraft && aircraft.type) {
  payload.model = aircraft.manufacturer ? `${aircraft.manufacturer} ${aircraft.type}` : aircraft.type;
  if (aircraft.manufacturer) payload.make = aircraft.manufacturer;
  if (aircraft.icao_type) payload.modelShort = aircraft.icao_type;
}

return [{ json: payload }];
